import sys;sys.path.insert(0,__import__('os').path.dirname(__file__));from mk import I
CIR=("원 위의 점과 정점의 거리",[r"중심까지 거리 $d$, 반지름 $r$이면 원 위의 점까지 거리는 $|d-r|$부터 $d+r$까지."])

I('추가30·기하-16',"예상 오답 **54** — 최솟값을 $\\mathrm X=\\mathrm A$에서 잡은 경우",
 ["(나) $\\vec{\\mathrm{PQ}}\\parallel\\vec{\\mathrm{CB}}$와 (가) 정삼각형이 합쳐지면 P, Q는 직선 $y=x$에 대해 **대칭**입니다. 그래서 AP의 방향이 $\\frac{5\\pi}{12}$로 정해집니다.",
  "$|\\vec{\\mathrm{XB}}+\\vec{\\mathrm{XC}}|=2|\\vec{\\mathrm{XK}}|$ (K는 BC의 중점) → 선분 AP 위의 점에서 K까지 거리의 범위."],
 {'C2':("(가) 정삼각형",r"$|\vec{\mathrm{AP}}|=|\vec{\mathrm{AQ}}|=4$, $\angle\mathrm{PAQ}=\frac\pi3$."),
  'C3':("(나) 방향",r"$\vec{\mathrm{PQ}}$가 $(1,-1)$ 방향 → PQ $\perp$ $y=x$, 이등변이라 P, Q는 $y=x$ 대칭."),
  'C4':("(다) 위치",r"네 내적이 양수 → P, Q 모두 제1사분면."),
  'C5':("묻는 것",r"선분 AP 위의 X에 대해 $2|\vec{\mathrm{XK}}|$의 최대·최소.")},
 [("두 벡터의 합 → 중점",[r"$\vec{\mathrm{XB}}+\vec{\mathrm{XC}}=2\vec{\mathrm{XK}}$."]),
  ("점과 선분 사이 거리",[r"수선의 발이 선분 위에 있으면 그 거리가 최소. 최대는 두 끝점 중 하나."])],
 [("P, Q는 제1사분면",['C4','C2']),("$y=x$ 대칭과 방향각",['C3']),("중점 K",['C5']),("수선의 발과 최솟값",['C5']),("최댓값",['C5']),("답",['C5'])],
 [("수선의 발이 선분 위인가",'C5',[r"$3\sqrt2\cos\frac\pi6=\frac{3\sqrt6}2\approx3.67<4$이라 선분 AP 위. 아니면 최솟값은 끝점 P에서 납니다."]),
  ("방향각 $\\frac{5\\pi}{12}$",'C3',[r"$y=x$(각 $\frac\pi4$)에서 양쪽으로 $\frac\pi6$씩: $\frac\pi4\pm\frac\pi6$. P가 위쪽이라 $\frac{5\pi}{12}$."])],
 [("변형 · 직각삼각형을 작게",[r"$\overline{\mathrm{AB}}=\overline{\mathrm{AC}}=4$, $\angle\mathrm{BAC}=\frac\pi2$인 직각삼각형 ABC에 대하여 두 점 P, Q가 (가) 삼각형 APQ는 한 변의 길이가 $4$인 정삼각형, (나) 양수 $k$에 대하여 $\vec{\mathrm{PQ}}=k\vec{\mathrm{CB}}$, (다) $\vec{\mathrm{AB}}\cdot\vec{\mathrm{AP}}>0$, $\vec{\mathrm{AC}}\cdot\vec{\mathrm{AP}}>0$, $\vec{\mathrm{AB}}\cdot\vec{\mathrm{AQ}}>0$, $\vec{\mathrm{AC}}\cdot\vec{\mathrm{AQ}}>0$을 만족시킨다. 선분 AP 위의 점 X에 대하여 $|\vec{\mathrm{XB}}+\vec{\mathrm{XC}}|$의 최댓값을 $M$, 최솟값을 $m$이라 할 때, $M^2+m^2$의 값을 구하시오."],40,r"K$(2,2)$, $\overline{\mathrm{AK}}=2\sqrt2$, 수선 길이 $\sqrt2$ (발은 선분 위) → $m=2\sqrt2$, $M=2\cdot2\sqrt2$ (X$=$A). $8+32$.")],
 "두 점 벡터의 합은 중점까지의 거리. 선분 위 점까지의 거리는 수선의 발이 선분 위인지부터.")

I('추가30·기하-17',"예상 오답 **28** — 넓이를 다른 방향(벡터를 $+x$ 방향)으로 잡고 계산한 경우",
 ["$\\vec{\\mathrm{PB}}=\\vec{\\mathrm{EB}}-\\vec{\\mathrm{EP}}$처럼 쪼개면 $\\vec{\\mathrm{AX}}$ = (고정 벡터 $(3,0)$) − (길이 $1,2,1$인 세 벡터의 합). 최대는 세 벡터가 **모두 $(-1,0)$ 방향**일 때.",
  "등호 조건이 P, Q, R의 위치를 하나로 정해 주니 삼각형 넓이까지 계산됩니다."],
 {'C1':("정사각형과 내분점",r"E$(0,3)$, F$(1,0)$, G$(4,1)$ (A$(0,4)$, B 원점)."),
  'C3':("(가) 세 원",r"P, Q, R는 각각 E, F, G 중심, 반지름 $1,2,1$인 원 위."),
  'C4':("(나) 벡터 합",r"$\vec{\mathrm{AX}}=(\vec{\mathrm{EB}}+\vec{\mathrm{FC}}+\vec{\mathrm{GD}})-(\vec{\mathrm{EP}}+\vec{\mathrm{FQ}}+\vec{\mathrm{GR}})$."),
  'C5':("묻는 것",r"최댓값 $M$과 그때의 삼각형 PQR의 넓이 $S$.")},
 [("벡터 쪼개기",[r"$\vec{\mathrm{PB}}=\vec{\mathrm{PE}}+\vec{\mathrm{EB}}$. 원의 중심을 거쳐 가면 고정 부분과 움직이는 부분이 분리됩니다."]),
  ("삼각부등식의 등호",[r"$|\vec c-\vec v|\le|\vec c|+|\vec v|$, 등호는 $\vec v$가 $-\vec c$ 방향."])],
 [("쪼개기",['C4']),("정리",['C4']),("좌표와 고정 벡터",['C1']),("최댓값 7과 등호 조건",['C3']),("P, Q, R와 넓이",['C5']),("답",['C5'])],
 [("세 벡터의 방향",'C3',[r"고정 벡터 $(3,0)$에서 빼므로 움직이는 벡터는 $(-1,0)$ 방향이어야 더해집니다. 부호를 놓치면 넓이가 바뀝니다."])],
 [("변형 · 반지름 2, 2, 1",[r"한 변의 길이가 $4$인 정사각형 ABCD에서 선분 AB, BC, CD를 각각 $1:3$으로 내분하는 점을 E, F, G라 하자. 네 점 P, Q, R, X가 $|\vec{\mathrm{EP}}|=2$, $|\vec{\mathrm{FQ}}|=2$, $|\vec{\mathrm{GR}}|=1$, $\vec{\mathrm{AX}}=\vec{\mathrm{PB}}+\vec{\mathrm{QC}}+\vec{\mathrm{RD}}$를 만족시킨다. $|\vec{\mathrm{AX}}|$의 최댓값을 $M$, 그때 삼각형 PQR의 넓이를 $S$라 할 때, $M\times S$의 값을 구하시오."],52,r"$M=3+5=8$, P$(-2,3)$, Q$(-1,0)$, R$(3,1)$, $S=\frac{13}2$.")],
 "원의 중심을 거쳐 벡터를 쪼갠다. 최대는 움직이는 벡터가 모두 한 방향.")

I('추가30·기하-18',"예상 오답 **33** — 안쪽 정사각형을 빼지 않은 경우",
 ["$\\vec{\\mathrm{QX}}=\\vec{\\mathrm{OP}}$ → X는 정사각형 둘레 위 어떤 점에서 **거리가 정확히 1**인 점. 둘레를 따라 Q를 움직이면 거리가 연속으로 변하므로 ‘둘레까지 거리 $\\le1$’인 점은 모두 가능합니다.",
  "영역 = 둘레를 두께 $2$로 칠한 띠. 바깥으로 둥근 모서리, 안쪽은 작은 정사각형이 빠집니다."],
 {'C1':("원과 정사각형",r"P는 단위원 위, Q는 한 변 $4$인 정사각형 둘레 위."),
  'C2':("벡터 합",r"X = Q + (단위벡터). 둘레 위 한 점을 중심으로 하는 단위원 위."),
  'C3':("영역의 넓이",r"$a+b\pi$ 꼴.")},
 [("민코프스키 합",[r"도형 + 원 = 도형을 원으로 ‘두르기’. 볼록 도형의 둘레를 두르면 바깥은 둥근 모서리, 안쪽은 빈 공간."]),
  ("중간값 정리 감각",[r"둘레 위에서 거리가 $1$ 이하인 점과 $1$ 이상인 점이 둘 다 있으면, 그 사이에 정확히 $1$인 점이 있습니다."])],
 [("X의 의미",['C2']),("가능한 점의 조건",['C2']),("영역의 모양",['C3']),("넓이",['C3']),("답",['C3'])],
 [("안쪽 구멍",'C3',[r"둘레에서 $1$보다 먼 안쪽 정사각형 $(1,3)\times(1,3)$은 X가 될 수 없습니다. 넓이 $4$를 빼야 합니다."]),
  ("거리가 ‘정확히’ 1",'C2',[r"원 위의 점이라 거리는 정확히 $1$이지만, Q가 둘레 전체를 움직이니 결과 영역은 채워진 띠입니다."])],
 [("변형 · 한 변 6",[r"원 $x^2+y^2=1$ 위를 움직이는 점 P와 네 점 $(0,0)$, $(6,0)$, $(6,6)$, $(0,6)$을 꼭짓점으로 하는 정사각형의 네 변 위를 움직이는 점 Q에 대하여 $\vec{\mathrm{OX}}=\vec{\mathrm{OP}}+\vec{\mathrm{OQ}}$를 만족시키는 모든 점 X가 나타내는 영역의 넓이가 $a+b\pi$일 때, $a+b$의 값을 구하시오. (단, $a$, $b$는 유리수)"],45,r"$(36+4\times6+\pi)-4^2=44+\pi$.")],
 "점 + 원 = 그 점의 자취를 두께 $2r$로 두르기. 안쪽에 남는 구멍을 확인.")

I('추가30·기하-19',"예상 오답 **7** — 두 호 중 하나만 센 경우",
 ["$\\vec{\\mathrm{PQ}}=\\vec{\\mathrm{AB}}$이면 Q = P + (4,0). P가 A쪽 원, Q가 B쪽 원 위에 있어야 하고, $\\vec{\\mathrm{AP}}=\\vec{\\mathrm{BQ}}$가 같은 단위벡터의 2배가 됩니다.",
  "$|\\vec{\\mathrm{OX}}|\\ge2$ 조건이 각도를 $\\cos\\theta\\in[-\\frac12,\\frac12]$로 자릅니다. Y = 4u는 반지름 4인 원의 **두 호**."],
 {'C2':("도형",r"A 또는 B 중심, 반지름 $2$인 두 원 중 원점에서 $2$ 이상 떨어진 부분."),
  'C3':("평행이동 관계",r"Q = P + $(4,0)$."),
  'C4':("묻는 것",r"$\vec{\mathrm{OY}}=\vec{\mathrm{OP}}+\vec{\mathrm{OQ}}=4\vec u$의 자취 길이.")},
 [("$\\vec{\\mathrm{PQ}}=\\vec v$ → 평행이동",[r"P가 있는 도형을 $\vec v$만큼 옮긴 도형과 원래 도형이 만나는 곳에 Q가 있습니다."]),
  ("호의 길이",[r"반지름 $r$, 중심각 $\theta$ → $r\theta$."])],
 [("Q = P + (4,0)",['C3']),("P가 B쪽 원이면 모순",['C2']),("$\\vec{\\mathrm{AP}}=\\vec{\\mathrm{BQ}}=2\\vec u$",['C2','C3']),("거리 조건",['C2']),("각의 범위",['C2']),("Y의 자취",['C4'])],
 [("경우 하나를 버리는 근거",'C2',[r"P가 B쪽 원 위면 Q는 $(6,0)$ 중심 원 위 → 도형과 만나는 점은 $(4,0)$뿐, 그때 P$=$O라 $|\vec{\mathrm{OP}}|\ge2$에 모순."]),
  ("호는 두 개",'C4',[r"$\cos\theta\in[-\frac12,\frac12]$는 위쪽·아래쪽 두 구간. 중심각 합 $\frac{2\pi}3$."])],
 [("변형 · 크기 3",[r"좌표평면 위의 두 점 A$(-3,0)$, B$(3,0)$에 대하여 $(|\vec{\mathrm{AX}}|-3)(|\vec{\mathrm{BX}}|-3)=0$, $|\vec{\mathrm{OX}}|\ge3$을 만족시키는 점 X가 나타내는 도형 위의 두 점 P, Q가 $\vec{\mathrm{PQ}}=\vec{\mathrm{AB}}$를 만족시킨다. $\vec{\mathrm{OY}}=\vec{\mathrm{OP}}+\vec{\mathrm{OQ}}$를 만족시키는 점 Y가 나타내는 도형의 길이가 $\frac qp\pi$일 때, $p+q$의 값을 구하시오. (단, $p$, $q$는 서로소인 자연수)"],5,r"$|\vec{\mathrm{OP}}|^2=18-18\cos\theta\ge9$ 등 → $\cos\theta\in[-\frac12,\frac12]$. Y$=6\vec u$, 길이 $6\times\frac{2\pi}3=4\pi$.")],
 "$\\vec{\\mathrm{PQ}}=\\vec v$는 평행이동. 거리 조건이 각을 잘라 호를 만든다.")

I('추가30·기하-20',"예상 오답 **96** — $\\vec{\\mathrm{AQ}}\\cdot\\vec{\\mathrm{AD}}$의 범위를 $[0,16]$으로 둔 경우",
 ["$\\vec{\\mathrm{AX}}=\\frac12(\\vec{\\mathrm{AP}}+\\vec{\\mathrm{AQ}})$이므로 내적도 반반. P와 Q는 **독립**이라 각각의 범위를 따로 구해 더하면 됩니다.",
  "$\\vec{\\mathrm{AQ}}\\cdot\\vec{\\mathrm{AD}}=16+\\vec{\\mathrm{DQ}}\\cdot\\vec{\\mathrm{AD}}$, 뒤 항은 $\\pm4$."],
 {'C1':("정육각형과 원",r"한 변 $2$인 정육각형 둘레 위의 P, D 중심 반지름 $1$인 원 위의 Q. $\overline{\mathrm{AD}}=4$."),
  'C2':("벡터식",r"X는 P와 Q의 중점 (A 기준)."),
  'C4':("묻는 것",r"$\vec{\mathrm{AX}}\cdot\vec{\mathrm{AD}}$의 최대·최소의 곱.")},
 [("정사영과 내적",[r"$\vec{\mathrm{AP}}\cdot\vec{\mathrm{AD}}=\overline{\mathrm{AD}}\times$(P의 AD 방향 정사영 길이)."]),
  ("독립인 두 점",[r"$f(\mathrm P)+g(\mathrm Q)$의 범위는 각 범위의 합."])],
 [("내적을 반반",['C2']),("P 부분 $[0,16]$",['C1']),("Q 부분 $[12,20]$",['C1']),("답",['C4'])],
 [("Q 부분을 D 기준으로",'C1',[r"$\vec{\mathrm{AQ}}=\vec{\mathrm{AD}}+\vec{\mathrm{DQ}}$. D 기준으로 쪼개야 원의 반지름이 그대로 들어갑니다."])],
 [("변형 · $|\\vec{\\mathrm{DQ}}|=2$",[r"한 변의 길이가 $2$인 정육각형 ABCDEF의 변 위를 움직이는 점 P와 $|\vec{\mathrm{DQ}}|=2$를 만족시키는 점 Q에 대하여 점 X가 $\vec{\mathrm{AX}}=\frac12(\vec{\mathrm{AP}}+\vec{\mathrm{AQ}})$를 만족시킨다. $\vec{\mathrm{AX}}\cdot\vec{\mathrm{AD}}$의 최댓값과 최솟값의 곱을 구하시오."],80,r"Q 부분 $16\pm8$ → $[8,24]$, 합 $[8,40]$, 절반 $[4,20]$.")],
 "독립인 두 점의 식은 따로 범위를 구해 더한다. 원 위 점은 중심을 거쳐 쪼갠다.")
